use clap::{Parser, Subcommand};
use colored::*;
use dirs::config_dir;
use git2::{Repository, Signature};
use serde::{Deserialize, Serialize};
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::{Path, PathBuf};
use tempfile::NamedTempFile;

#[derive(Parser)]
#[command(name = "eureka")]
#[command(about = "Input and store your ideas without leaving the terminal", long_about = None)]
#[command(version = "2.0.0")]
struct Args {
    /// Clear your stored configuration
    #[arg(long)]
    clear_config: bool,

    /// View ideas with your $PAGER env variable. If unset use less
    #[arg(short, long)]
    view: bool,
}

#[derive(Serialize, Deserialize, Debug)]
struct Config {
    repo: PathBuf,
}

fn main() {
    let args = Args::parse();

    if args.clear_config {
        clear_config();
        return;
    }

    if args.view {
        view_ideas();
        return;
    }

    // Default action: record a new idea
    record_idea();
}

fn get_config_path() -> PathBuf {
    let mut path = config_dir().expect("Could not find config directory");
    path.push("eureka");
    path
}

fn get_config_file() -> PathBuf {
    let mut path = get_config_path();
    path.push("config.json");
    path
}

fn load_config() -> Option<Config> {
    let config_file = get_config_file();
    if config_file.exists() {
        let contents = fs::read_to_string(&config_file).ok()?;
        serde_json::from_str(&contents).ok()
    } else {
        None
    }
}

fn save_config(config: &Config) -> Result<(), Box<dyn std::error::Error>> {
    let config_path = get_config_path();
    fs::create_dir_all(&config_path)?;
    let config_file = get_config_file();
    let contents = serde_json::to_string(config)?;
    fs::write(&config_file, contents)?;
    Ok(())
}

fn clear_config() {
    let config_file = get_config_file();
    if config_file.exists() {
        let _ = fs::remove_file(&config_file);
    }
}

fn is_absolute_path(path: &str) -> bool {
    Path::new(path).is_absolute()
}

fn first_time_setup() -> Config {
    println!("{}", "############################################################".yellow());
    println!("{}", "####                  First Time Setup                  ####".yellow());
    println!("{}", "############################################################".yellow());
    println!();
    println!("This tool requires you to have a repository with a README.md");
    println!("in the root folder. The markdown file is where your ideas");
    println!("will be stored.");
    println!();
    println!("Once first time setup has completed, simply run Eureka again");
    println!("to begin writing down ideas.");
    println!();

    loop {
        print!("{} ", "Absolute path to your idea repo".green().bold());
        io::stdout().flush().unwrap();

        let stdin = io::stdin();
        let mut line = String::new();
        stdin.lock().read_line(&mut line).unwrap();
        let path = line.trim().to_string();

        if !is_absolute_path(&path) {
            println!("{}", "Path must be absolute".red());
            continue;
        }

        // Verify the path exists and has a README.md
        let repo_path = PathBuf::from(&path);
        if !repo_path.exists() {
            println!("{}", "Path does not exist".red());
            continue;
        }

        let readme_path = repo_path.join("README.md");
        if !readme_path.exists() {
            println!("{}", "README.md does not exist in the repository".red());
            continue;
        }

        let config = Config {
            repo: repo_path,
        };

        if save_config(&config).is_ok() {
            println!("{}", "First time setup complete. Happy ideation!".green());
            return config;
        }
    }
}

fn record_idea() {
    let config = match load_config() {
        Some(cfg) => cfg,
        None => first_time_setup(),
    };

    // Prompt for idea summary
    print!("{} ", ">> Idea summary".green().bold());
    io::stdout().flush().unwrap();

    let stdin = io::stdin();
    let mut summary = String::new();
    stdin.lock().read_line(&mut summary).unwrap();
    let summary = summary.trim().to_string();

    // Open editor for the actual idea content
    let content = open_editor().expect("Failed to open editor");

    if content.trim().is_empty() {
        println!("Idea is empty, aborting.");
        return;
    }

    // Add to git repo
    println!("{}", "Adding and committing your new idea to main..".green().bold());

    match add_to_repo(&config.repo, &summary, &content) {
        Ok(_) => {
            println!("{}", "Added and committed!".green());
            println!("{}", "Pushing your new idea..".green().bold());

            // Try to push - it may fail if there's no origin
            match push_to_origin(&config.repo) {
                Ok(_) => println!("{}", "Pushed!".green()),
                Err(e) => {
                    eprintln!(" {} eureka > {}", "ERROR".red(), e);
                }
            }
        }
        Err(e) => {
            eprintln!(" {} eureka > {}", "ERROR".red(), e);
        }
    }
}

fn open_editor() -> Result<String, Box<dyn std::error::Error>> {
    let editor = std::env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());

    // Create a temporary file
    let mut temp_file = NamedTempFile::new()?;
    let temp_path = temp_file.path().to_path_buf();

    // Run the editor
    let status = std::process::Command::new(&editor)
        .arg(&temp_path)
        .status()?;

    if !status.success() {
        return Err("Editor exited with non-zero status".into());
    }

    // Read the file content
    let content = fs::read_to_string(&temp_path)?;
    Ok(content)
}

fn add_to_repo(
    repo_path: &Path,
    summary: &str,
    content: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let repo = Repository::open(repo_path)?;

    // Write content to README.md
    let readme_path = repo_path.join("README.md");
    fs::write(&readme_path, content)?;

    // Stage the changes
    let mut index = repo.index()?;
    index.add_path(Path::new("README.md"))?;
    index.write()?;

    // Get the current signature
    let config = repo.config()?;
    let name = config.get_string("user.name")?;
    let email = config.get_string("user.email")?;
    let sig = Signature::now(&name, &email)?;

    // Create the tree
    let tree_id = index.write_tree()?;
    let tree = repo.find_tree(tree_id)?;

    // Get the parent commit
    let head = repo.head()?;
    let parent_commit = repo.find_commit(head.target().unwrap())?;

    // Create the commit
    repo.commit(
        Some("HEAD"),
        &sig,
        &sig,
        summary,
        &tree,
        &[&parent_commit],
    )?;

    Ok(())
}

fn push_to_origin(repo_path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let repo = Repository::open(repo_path)?;

    // Try to get the remote
    let mut remote = repo.find_remote("origin")?;

    // Push to origin main/master
    let branch_name = match repo.head() {
        Ok(head) => {
            if let Some(name) = head.shorthand() {
                name
            } else {
                "main"
            }
        }
        Err(_) => "main",
    };

    let refspec = format!("refs/heads/{}:refs/heads/{}", branch_name, branch_name);
    remote.push(&[refspec.as_str()], None)?;

    Ok(())
}

fn view_ideas() {
    let config = match load_config() {
        Some(cfg) => cfg,
        None => {
            eprintln!("No configuration found. Please run eureka first.");
            std::process::exit(1);
        }
    };

    let readme_path = config.repo.join("README.md");
    if !readme_path.exists() {
        eprintln!("README.md not found in the repository.");
        std::process::exit(1);
    }

    // Use PAGER if available, otherwise use less
    let pager = std::env::var("PAGER").unwrap_or_else(|_| "less".to_string());

    // Read the content
    let content = fs::read_to_string(&readme_path).expect("Failed to read README.md");

    // Pipe to pager
    let mut child = std::process::Command::new("sh")
        .arg("-c")
        .arg(format!("echo '{}' | {}", content.replace("'", "'\\''"), pager))
        .spawn()
        .expect("Failed to spawn pager");

    let _ = child.wait();
}
