use std::fs;
use std::io::{self, BufRead, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

fn main() {
    let args: Vec<String> = std::env::args().collect();

    if args.len() > 1 {
        match args[1].as_str() {
            "--help" | "-h" => print_help(),
            "--version" | "-V" => print_version(),
            "--clear-config" => clear_config(),
            "--view" | "-v" => view_ideas(),
            _ => print_help(),
        }
    } else {
        record_idea();
    }
}

fn print_help() {
    println!("Input and store your ideas without leaving the terminal\n");
    println!("Usage: eureka [OPTIONS]\n");
    println!("Options:");
    println!("      --clear-config  Clear your stored configuration");
    println!("  -v, --view          View ideas with your $PAGER env variable. If unset use less");
    println!("  -h, --help          Print help");
    println!("  -V, --version       Print version");
}

fn print_version() {
    println!("eureka 2.0.0");
}

fn get_config_path() -> PathBuf {
    let home = std::env::var("HOME").expect("HOME not set");
    let mut path = PathBuf::from(home);
    path.push(".config");
    path.push("eureka");
    path
}

fn get_config_file() -> PathBuf {
    let mut path = get_config_path();
    path.push("config.json");
    path
}

fn load_config() -> Option<String> {
    let config_file = get_config_file();
    if config_file.exists() {
        fs::read_to_string(&config_file).ok()
    } else {
        None
    }
}

fn get_repo_from_config(config: &str) -> Option<String> {
    // Simple JSON parsing for {"repo":"path"}
    if let Some(start) = config.find("\"repo\"") {
        if let Some(colon_pos) = config[start..].find(':') {
            let after_colon = &config[start + colon_pos + 1..];
            if let Some(quote_start) = after_colon.find('"') {
                let after_quote = &after_colon[quote_start + 1..];
                if let Some(quote_end) = after_quote.find('"') {
                    return Some(after_quote[..quote_end].to_string());
                }
            }
        }
    }
    None
}

fn save_config(repo_path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let config_path = get_config_path();
    fs::create_dir_all(&config_path)?;
    let config_file = get_config_file();
    let config_json = format!("{{\"repo\":\"{}\"}}", repo_path);
    fs::write(&config_file, config_json)?;
    Ok(())
}

fn clear_config() {
    let config_file = get_config_file();
    if config_file.exists() {
        let _ = fs::remove_file(&config_file);
    }
}

fn is_absolute_path(path: &str) -> bool {
    Path::new(path).is_absolute()
}

