}

fn color_red(s: &str) -> String {
    format!("\x1b[31m{}\x1b[0m", s)
}

fn color_bold_green(s: &str) -> String {
    format!("\x1b[1m\x1b[32m{}\x1b[0m", s)
}

fn first_time_setup() -> String {
    println!("{}", color_yellow("############################################################"));
    println!("{}", color_yellow("####                  First Time Setup                  ####"));
    println!("{}", color_yellow("############################################################"));
    println!();
    println!("This tool requires you to have a repository with a README.md");
    println!("in the root folder. The markdown file is where your ideas");
    println!("will be stored.");
    println!();
    println!("Once first time setup has completed, simply run Eureka again");
    println!("to begin writing down ideas.");
    println!();

    loop {
        print!("{} ", color_bold_green("Absolute path to your idea repo"));
        io::stdout().flush().unwrap();

        let stdin = io::stdin();
        let mut line = String::new();
        stdin.lock().read_line(&mut line).unwrap();
        let path = line.trim().to_string();

        if !is_absolute_path(&path) {
            println!("{}", color_red("Path must be absolute"));
            continue;
        }

        // Verify the path exists and has a README.md
        let repo_path = PathBuf::from(&path);
        if !repo_path.exists() {
            println!("{}", color_red("Path does not exist"));
            continue;
        }

        let readme_path = repo_path.join("README.md");
        if !readme_path.exists() {
            println!("{}", color_red("README.md does not exist in the repository"));
            continue;
        }

        if save_config(&path).is_ok() {
            println!("{}", color_green("First time setup complete. Happy ideation!"));
            return path;
        }
    }
}

fn record_idea() {
    let repo_path = match load_config() {
        Some(config) => match get_repo_from_config(&config) {
            Some(path) => path,
            None => first_time_setup(),
        },
        None => first_time_setup(),
    };

    // Prompt for idea summary
    print!("{} ", color_bold_green(">> Idea summary"));
    io::stdout().flush().unwrap();

    let stdin = io::stdin();
    let mut summary = String::new();
    stdin.lock().read_line(&mut summary).unwrap();
    let summary = summary.trim().to_string();

    // Open editor for the actual idea content
    let content = match open_editor() {
        Ok(c) => c,
        Err(e) => {
            eprintln!(" {} eureka > {}", color_red("ERROR"), e);
            return;
        }
    };

    if content.trim().is_empty() {
        println!("Idea is empty, aborting.");
        return;
    }

    // Add to git repo
    println!("{} ", color_bold_green("Adding and committing your new idea to main.."));

    match add_to_repo(&repo_path, &summary, &content) {
        Ok(_) => {
            println!("{}", color_green("Added and committed!"));
            println!("{} ", color_bold_green("Pushing your new idea.."));

            // Try to push - it may fail if there's no origin
            match push_to_origin(&repo_path) {
                Ok(_) => println!("{}", color_green("Pushed!")),
                Err(e) => {
                    eprintln!(" {} eureka > {}", color_red("ERROR"), e);
                }
            }
        }
        Err(e) => {
            eprintln!(" {} eureka > {}", color_red("ERROR"), e);
        }
    }
}

fn open_editor() -> Result<String, Box<dyn std::error::Error>> {
    let editor = std::env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());

    // Create a temporary file path
    let temp_path = format!("/tmp/eureka_{}.txt", std::process::id());

    // Run the editor
    let status = Command::new(&editor)
        .arg(&temp_path)
        .status()?;

    if !status.success() {
        return Err("Editor exited with non-zero status".into());
    }

    // Read the file content
    let content = fs::read_to_string(&temp_path)?;

    // Clean up
    let _ = fs::remove_file(&temp_path);

    Ok(content)
}

fn add_to_repo(
    repo_path: &str,
    summary: &str,
    content: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let repo_path_obj = Path::new(repo_path);

    // Write content to README.md
    let readme_path = repo_path_obj.join("README.md");
    fs::write(&readme_path, content)?;

    // Stage and commit using git command
    let mut cmd = Command::new("git");
    cmd.current_dir(repo_path);
    cmd.arg("add").arg("README.md");
    let status = cmd.status()?;
    if !status.success() {
        return Err("git add failed".into());
    }

    let mut cmd = Command::new("git");
    cmd.current_dir(repo_path);
    cmd.arg("commit").arg("-m").arg(summary);
    let status = cmd.status()?;
    if !status.success() {
        return Err("git commit failed".into());
    }

    Ok(())
}

fn push_to_origin(repo_path: &str) -> Result<(), Box<dyn std::error::Error>> {
    // Get current branch
    let mut cmd = Command::new("git");
    cmd.current_dir(repo_path);
    cmd.arg("rev-parse").arg("--abbrev-ref").arg("HEAD");
    let output = cmd.output()?;
    let branch = String::from_utf8(output.stdout)?
        .trim()
        .to_string();

    let refspec = format!("{}:{}", branch, branch);

    // Try to push
    let mut cmd = Command::new("git");
    cmd.current_dir(repo_path);
    cmd.arg("push").arg("origin").arg(&refspec);
    let status = cmd.status()?;
    if !status.success() {
        return Err("git push failed".into());
    }

    Ok(())
}

fn view_ideas() {
    let config = match load_config() {
        Some(cfg) => cfg,
        None => {
            eprintln!("No configuration found. Please run eureka first.");
            std::process::exit(1);
        }
    };

    let repo_path = match get_repo_from_config(&config) {
        Some(path) => path,
        None => {
            eprintln!("Invalid configuration.");
            std::process::exit(1);
        }
    };

    let readme_path = Path::new(&repo_path).join("README.md");
    if !readme_path.exists() {
        eprintln!("README.md not found in the repository.");
        std::process::exit(1);
    }

    // Use PAGER if available, otherwise use less
    let pager = std::env::var("PAGER").unwrap_or_else(|_| "less".to_string());

    // Read the content
    let content = fs::read_to_string(&readme_path).expect("Failed to read README.md");

    // Pipe to pager using cat with echo or directly with printf
    let status = Command::new("sh")
        .arg("-c")
        .arg(format!("echo {} | {}", 
            format!("{:?}", content), // This will quote it but with escaping issues
            pager
        ))
        .status();

    if status.is_err() {
        // Fallback: just print content
        println!("{}", content);
    }
}
